/********************************************** 
 * 함수명   : ins_search
 * 설명       : CFI/FISN 정합성체크 조회 한다.
 ***********************************************/
scwin.ins_search = function() {
    //var argv = fn_listNewIDChg.arguments;
    //var argc = fn_listNewIDChg.arguments.length;
    //vPAGENO = (argc == 0) ? 0 : vPAGENO = argv[0];

    $c.cm.ShowWin(grd_Grid);
    var url = "/EtcInfoAction.do?method=listCfiValdChk";
    url += "&ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD);
    url += "&STD_CD=" + $c.stf.getObjectValue(txb_STD_CD);
    url += "&ISU_NM=" + $c.stf.getObjectValue(txb_ISU_NM);
    url += "&SDATE=" + $c.stf.getObjectValue(edt_SDATE);
    url += "&EDATE=" + $c.stf.getObjectValue(edt_EDATE);
    url += "&ACTIV_TP_CD=" + $c.stf.getObjectValue(cmb_pACTIV_YN);
    url += "&CKB_CFI=" + $c.stf.getObjectValue(ckb_CFI);
    url += "&CKB_FISN=" + $c.stf.getObjectValue(ckb_FISN);
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

    //alert(url);
    dts_List.DataID = encodeURI(url);
    dts_List.Reset();

    /*var url = "/listingCommon.do?SCREN_ID="+vScrenID+"&SCREN_PROCES_TP_CD="+SCREN_PROCS_TP_CD_01+"&method=listGeneralForDynamicName" +
    "&outputMessageId=ULDINS21600_LIST_OUT" +
    "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + 
    "&queryId=lds.ins.etc.select.listCfiValdChk";
    //"&{P}SDATE=" +  edt_SDATE.text +
    //"&{P}EDATE=" +  edt_EDATE.text +
    //"&{P}STD_CD=" +  getObjectValue(txb_STD_CD)  ;

    //alert(getObjectValue(cmb_pISUR_APPL_TP_CD));
    // alert(getObjectValue(cmb_pPROC));

    dts_List.DataID = encodeURI(url);
    dts_List.reset();
    ShowWin(grd_Grid); // 그리드명을 표기*/

};



/********************************************** 
 * 함수명  : fn_SetBgColor_list
 * 설명      : 개선사항 유무에 따른 배경색 설정
 ***********************************************/
scwin.fn_SetBgColor_list = function() {
    //그리드 컬럼 ID 구하기
    var arrColID = [];
    for (var i = 0; i < grd_Grid.getTotalCol(); i++) {
        arrColID.push(grd_Grid.getColumnID(i));
    }

    //CFI코드 FISN코드 배경색 설정
    for (var j = 0; j < arrColID.length; j++) {
        if (arrColID[j] == 'CFI_CD' || arrColID[j] == 'TO_CFI_CD') {
            $c.cm.setColumnProp(grd_Grid, arrColID[j], 'BgColor', "{decode(CFI_IMPR_REQ_YN,'Y','#FF9900',decode(currow-tointeger(currow/2)*2,0,'#f2f5f9','#ffffff'))}");
        } else if (arrColID[j] == 'FISN_VAL' || arrColID[j] == 'TO_FISN_VAL') {
            $c.cm.setColumnProp(grd_Grid, arrColID[j], 'BgColor', "{decode(FISN_IMPR_REQ_YN,'Y','#FFFF99',decode(currow-tointeger(currow/2)*2,0,'#f2f5f9','#ffffff'))}");
        } else {
            $c.cm.setColumnProp(grd_Grid, arrColID[j], 'BgColor', "{decode(currow-tointeger(currow/2)*2,0,'#f2f5f9','#ffffff')}");
        }
    }
};




/********************************************** 
 * 함수명   : ins_all_save
 * 설명       : 일괄저장
 ***********************************************/
scwin.ins_all_save = function() {
    if (js_svrGubun == 'dr') {
        $c.win.alert("DR에서 운영될때는 서비스가 제공되지 않습니다.");
        return;
    }
    if (scwin.fn_chkValid() == false) {
        $c.win.alert("CFI정합성 적용대상을 선택하세요.");
        return;
    }
    if (scwin.fn_chkValidSixLength() == false) {
        $c.win.alert("6자리가 아닌 CFI코드가 존재합니다.");
        return;
    }
    if (!confirm("저장하시겠습니까?")) {
        return;
    }
    trs_autosave.Action = "/EtcInfoAction.do?method=registerCfiValdChk" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    trs_autosave.KeyName = "toinb_dataid4";
    trs_autosave.KeyValue = "JSP(O:pReturnOut=dts_Rst,I:pInputMaster=dts_List)";
    trs_autosave.Parameters = "EMP_NO=" + js_emp_no + ",EMP_NM=" + js_emp_nm + ",EMAIL=" + js_email;
    trs_autosave.Post();
};


/********************************************** 
 * 함수명   : fn_chkValid
 * 설명       : 일괄저장 체크대상을 알아낸다.
 ***********************************************/
scwin.fn_chkValid = function() {
    var cnt = 0;
    for (var nRow = 1; nRow <= dts_List.getTotalRow(); nRow++) {
        if (dts_List.getCellData(nRow, "CHK") == "T") {
            cnt++;
        }
    }
    //alert("cnt " +cnt);
    if (eval(cnt) > 0) {
        return true;
    } else {
        return false;
    }
};



/********************************************** 
 * 함수명   : fn_chkValidSixLength
 * 설명       : 일괄저장시 CFI 6자리 체크
 ***********************************************/
scwin.fn_chkValidSixLength = function() {
    var cnt = 0;
    for (var nRow = 1; nRow <= dts_List.getTotalRow(); nRow++) {
        //alert(dts_List.NameString(nRow, "TO_CFI_CD").replace("_","").length);
        if (dts_List.getCellData(nRow, "CHK") == "T") {
            if (dts_List.getCellData(nRow, "TO_CFI_CD").replace("_", "").length < 6) {
                cnt++;
            }
        }
    }
    //alert("cnt " +cnt);
    if (eval(cnt) > 0) {
        return false;
    } else {
        return true;
    }
};
scwin.arrPar = new Array();
/********************************************** 
 * 함수명   : fn_GetParam
 * 설명       : 전달값을 설정한다.
 ***********************************************/
scwin.fn_GetParam = function(arrPar) {
    scwin.arrPar[0] = txb_param1.getValue(); // 발행기관코드  
    scwin.arrPar[1] = txb_param2.getValue(); // 발행기관코드명     

    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    scwin.arrPar, length;
};


/********************************************** 
 * 함수명   : fn_SelectAll
 * 설명       : 체크박스 전체선택
 ***********************************************/
scwin.fn_SelectAll = function() {
    grd_Grid.Redraw = false;
    if (scwin.gAllChk == false) {
        // 현재상태가 false이면 전체선택을 클릭한것

        scwin.gAllChk = true;
        for (var i = 0; i < dts_List.getTotalRow(); i++) {
            //if (dts_List.NameString(i + 1, "TO_CFI_LEN") == '6') { //수익처리대상여부
            //	dts_List.NameString(i + 1, "CHK") = "T";
            //} else {
            //	dts_List.NameString(i + 1, "CHK") = "F";
            //}
            dts_List.setCellData(i + 1, "CHK", "T");
        }
        btn_SelectedAll.setValue("전체해제");
    } else {
        // 현재상태가  true이면 전체선택을 클릭한것
        scwin.gAllChk = false;
        for (var i = 0; i < dts_List.getTotalRow(); i++) {
            dts_List.setCellData(i + 1, "CHK", "F");
        }
        btn_SelectedAll.setValue("전체선택");
    }
    grd_Grid.Redraw = true;
};


/**
 *  화면의 기본값 세팅
 */
scwin.fn_SetDefaultVal = function() {
    var sToday = $c.ut.cGetToday2();
    edt_SDATE.setValue(sToday);
    edt_EDATE.setValue(sToday);
};
scwin.grd_Grid_CanColumnPosChange = function(row, colid) {
    return true;
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_1);
    $c.stf.showObj(txb_param1, false);
    $c.stf.showObj(txb_param2, false);
    scwin.fn_SetDefaultVal();
    scwin.ins_search();
};
scwin.btn_search_onclick = function() {
    scwin.ins_search();
};
scwin.dts_List_OnLoadError = function(rowcount) {
    $c.stf.alert_error(dts_List);
    $c.cm.CloseWin(rowcount, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리	

};
scwin.img_SDATE_onclick = function() {
    popUpCalendar2(edt_SDATE);
};
scwin.img_EDATE_onclick = function() {
    popUpCalendar2(edt_EDATE);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    //alert('dts_List.OnLoadCompleted('+rowcount+')');
    if (dts_List.errorMsg) {
        $c.win.alert(dts_List.errorMsg);
    } else {
        txb_TotalCnt.setValue("총 " + rowcount + "건");
    }

    //fn_FisnVal();	//데이터처리 완료시 FISN 길이조정

    $c.cm.CloseWin(rowcount, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리

    scwin.gAllChk = false;
    btn_SelectedAll.setValue("전체선택");
    scwin.fn_SetBgColor_list(); //그리드 배경색 설정

};
scwin.btn_Save_onclick = function() {
    scwin.ins_all_save();
};
scwin.trs_autosave_OnFail = function() {
    alert_tr_error(trs_autosave);
};
scwin.btn_Excel_onclick = function() {
    var today = $c.ut.cGetToday("yyyymmddhhmmss");
    var title = "CFI정합성체크목록";
    var xls_path = $c.session.getExcelDownPath() + today + "_" + title + ".xls";
    $c.data.downloadGridViewOffice(grd_Grid, title, xls_path, 8, 0);
    //grd_Grid.GridToExcel(title, "", "8");

};
scwin.trs_autosave_OnFail = function() {
    alert_tr_error(trs_autosave);
};
scwin.trs_autosave_OnSuccess = function() {
    $c.win.alert("일괄 저장 되었습니다.");
    scwin.ins_search();
};
